const ateliers = JSON.parse(document.getElementById('app').dataset.ateliers || '[{"id":"py","titre":"Python"},{"id":"jar","titre":"Jardin"},{"id":"web","titre":"Web"}]');
function App() {
  const [recherche, setRecherche] = useState('');
  const terme = recherche.trim().toLowerCase();
  const [selection, setSelection] = useState(ateliers);
  useEffect(() => { setSelection(ateliers.filter(a => a.titre.toLowerCase().includes(terme))); }, []);
  useEffect(() => { document.title = selection.length + ' résultat(s)'; }, [selection.length]);
  return <main><h1>Catalogue fictif</h1><label htmlFor="recherche">Rechercher</label><input id="recherche" value={recherche} onChange={e => setRecherche(e.target.value)} /><ul id="liste">{selection.map(a => <li key={a.id}>{a.titre}</li>)}</ul><p id="compte" role="status">{selection.length} résultat(s)</p>{selection.length === 0 && <p id="vide">Aucun atelier.</p>}</main>;
}
root.render(<App />);

